#!/usr/bin/env python3
"""Normalize memory-tier `name:` frontmatter to the bare kebab-case form
(Option A) and repoint every [[wikilink]] at the new canonical names.

Canonical name = filename stem, minus a LEADING type token
(project|user|reference|feedback) followed by - or _, kebab-cased.

Deliberately derived from the FILENAME, not from the existing `name:` value:
stripping a prefix off `feedback_project_idea_capture.md`'s declared name
`project-idea-capture` would wrongly yield `idea-capture`.

Report-only unless --apply is passed.
"""
import os
import re
import sys
import argparse

ROOT = os.path.expanduser("~/.claude/projects")
RETIRED = "C--Users-eric-rash"
TYPE_TOKEN = re.compile(r"^(project|user|reference|feedback)[-_]")


def canonical(stem: str) -> str:
    """Filename stem -> canonical bare kebab-case name."""
    return TYPE_TOKEN.sub("", stem).replace("_", "-").lower()


def aliases(stem: str, declared: str | None) -> set[str]:
    """Every spelling a link might plausibly use for this file."""
    canon = canonical(stem)
    out = {
        canon,
        stem.lower(),
        stem.replace("_", "-").lower(),
        canon.replace("-", "_"),
    }
    for t in ("project", "user", "reference", "feedback"):
        out.add(f"{t}-{canon}")
        out.add(f"{t}_{canon}")
    if declared:
        out.add(declared.strip().strip('"').lower())
    return out


def slugs():
    for s in sorted(os.listdir(ROOT)):
        if s.startswith(RETIRED):
            continue
        mem = os.path.join(ROOT, s, "memory")
        if os.path.isdir(mem):
            yield s, mem


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--apply", action="store_true")
    args = ap.parse_args()

    renames, linkfixes, unresolved, collisions = [], [], [], []

    for slug, mem in slugs():
        files = [f for f in sorted(os.listdir(mem))
                 if f.endswith(".md") and f != "MEMORY.md"]

        # Pass 1 - build this slug's alias -> canonical resolution map.
        canon_of, alias_map, texts = {}, {}, {}
        for fn in files:
            path = os.path.join(mem, fn)
            txt = open(path, encoding="utf-8", errors="replace").read()
            texts[fn] = txt
            stem = fn[:-3]
            m = re.search(r"^name:\s*(.+)$", txt, re.M)
            declared = m.group(1).strip().strip('"') if m else None
            canon = canonical(stem)
            canon_of[fn] = (canon, declared)
            for a in aliases(stem, declared):
                alias_map.setdefault(a, set()).add(canon)

        # Two files claiming the same alias -> refuse to guess.
        ambiguous = {a for a, v in alias_map.items() if len(v) > 1}
        for a in sorted(ambiguous):
            collisions.append(f"{slug}: alias [[{a}]] matches {sorted(alias_map[a])}")

        valid = {c for c, _ in canon_of.values()}

        # Pass 2 - rewrite name: and links.
        for fn in files:
            path, txt = os.path.join(mem, fn), texts[fn]
            canon, declared = canon_of[fn]
            new = txt

            if declared is None:
                unresolved.append(f"{slug}/{fn}: no `name:` field - left alone")
            elif declared != canon:
                new = re.sub(r"^name:\s*.+$", f"name: {canon}", new, count=1, flags=re.M)
                renames.append(f"{slug}/{fn}: {declared} -> {canon}")

            def fix(mo):
                target = mo.group(1).strip()
                key = target.lower()
                if key in valid:
                    return f"[[{key}]]" if target != key else mo.group(0)
                hits = alias_map.get(key, set()) - ambiguous_for(key)
                if len(hits) == 1:
                    dest = next(iter(hits))
                    linkfixes.append(f"{slug}/{fn}: [[{target}]] -> [[{dest}]]")
                    return f"[[{dest}]]"
                unresolved.append(f"{slug}/{fn}: [[{target}]] unresolved - left alone")
                return mo.group(0)

            def ambiguous_for(key):
                return alias_map.get(key, set()) if key in ambiguous else set()

            new = re.sub(r"\[\[([^\]\|]+)\]\]", fix, new)

            if new != txt and args.apply:
                with open(path, "w", encoding="utf-8") as fh:
                    fh.write(new)

    def dump(title, rows):
        print(f"\n=== {title} ({len(rows)}) ===")
        for r in rows:
            print("  " + r)

    dump("NAME CHANGES", renames)
    dump("LINK FIXES", linkfixes)
    dump("COLLISIONS - not touched", collisions)
    dump("UNRESOLVED - left alone", unresolved)
    print(f"\nMode: {'APPLIED' if args.apply else 'DRY RUN'}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

